import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (search params `user` and `sheet`).
// Everything else in the app is kept per sheet: a feature reads the sheet id from here and keys
// its queries under ['sheet', sheetId, ...], so loading a sheet re-reads all of them.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// The active sheet as the store holds it: its id, its today and whether it is archived (then every
// change on it is refused). Every date decision and default
// date in the app uses the sheet's today (useSheetToday), never the browser's clock. In an as-of view
// (asof.slot.tsx) it is the sheet as it stood at the end of `asOf`, and that date is its today. Its
// lastBatch is the number of its last bulk settle batch (null while it has had none).
export type SheetInfo = { id: string; today: string; archived: boolean; asOf: string | null; lastBatch: number | null };

export const sheetQueryKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

export function useSheetInfo() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetQueryKey(sheet ?? ''),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}`),
    enabled: !!sheet,
  });
}

/** The sheet's today (YYYY-MM-DD), or undefined until the sheet is loaded. */
export const useSheetToday = () => useSheetInfo().data?.today;
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import type { Hold } from '../claims/claims';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

// `grade` is the grade in force on the sheet's today; `grades` every grade they were given with the date it
// applies from (null for the first, which applies from the beginning of time), by from-date.
// `version` is raised on every save; an edit sends the version it loaded and is refused (409) when
// someone else has saved the person since.
// `statementCount` is how many statements were taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and the sheet's today when it was taken (null with none).
// `retiredFrom` is the date they are retired from (null: not retired); with one set they count as retired at
// once, whatever the date; from the day it is reached (the sheet's today on or after it) their OPEN and PENDING
// claims count in no live total, as a hold's would, unless a statement binds them.
// `held`: whether they have any hold. `holds`: their holds, earliest from-date first; their OPEN and PENDING
// claims dated within one count in no live total, unless a statement binds them; their other claims still count.
// `terms`: their own terms in days (null: none); a claim of theirs is due by its date plus these, ahead of their
// grade's terms and the sheet's.
// `contact`: their contact, trimmed and lower-cased (null: none); no two people on a sheet share one.
// `aliases`: other names they go by, sorted ignoring case; the quick-add bar and the paste box find them by one too.
// `patronIds`: the other people on the sheet they have named as patrons, in the order they were named.
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: DatedGrade[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
};

/** A grade a person was given, from a date on (YYYY-MM-DD; null: from the beginning of time). */
export type DatedGrade = { grade: string; from: string | null };

/** The grade in force for a person on a date: the one whose from-date is the latest on or before it, the first
 *  grade they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found = person.grade;
  for (const g of person.grades) {
    if (g.from === null || g.from <= date) found = g.grade;
  }
  return found;
}

export const peopleQueryKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peoplePath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleQueryKey(sheet ?? ''),
    queryFn: () => getJson<Person[]>(peoplePath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open (search param `editPerson`), or '' for none. */
/** The mutation key of a person form save; an editor is not opened while one is on its way, so it never loads
 *  the person from before the save (nor is closed by it). */
export const personSaveKey = ['person-save'] as const;

export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether retired people are listed (search param `showRetired`): off when the screen is first opened, and
 *  left as it is by loading a sheet. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of view: while the screen's `asof` search param holds a date, every read of a sheet asks for the
// sheet as it stood at the end of that date, and every change is refused here, before it reaches the store
// (so each form and action shows its usual error). Loading a sheet (PUT /api/sheets/<id>) is not a change.
export const ASOF_PARAM = 'asof';

/** The date the screen shows the sheet as of (YYYY-MM-DD), or '' while it shows the sheet as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

const isSheetLoad = (path: string) => /^\/api\/sheets\/[^/?]+$/.test(path);

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const asOf = currentAsOf();
  if (asOf && init?.method && init.method !== 'GET' && !isSheetLoad(path)) {
    throw new HttpError(`${init.method} ${path} -> refused while the sheet is shown as of ${asOf}`, 400);
  }
  if (asOf && !init?.method && path.startsWith('/api/sheets/')) {
    path += `${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { settingOn, type Settings } from '../roles/roles';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A claim's status: DRAFT to start, then OPEN and SETTLED; a clerk settling one above the clerk limit leaves it
 *  PENDING, until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN or PENDING claim can be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim as the store holds it: the amount with two decimals, the date (YYYY-MM-DD), the note, the status and
 *  the number given when it was opened (the sheet's next, or the next in its period: P1-1, X-1; null for a claim never opened; a voided claim keeps it) and the due fixed when it was
 *  settled (null when it has none: its due is live), and who opened it (null when never opened); whether its person's last statement binds it, and the
 *  figure it binds it to (null: n/a); the number of the settled claim of the same person it corrects (null when it is not
 *  a correction — a correction is a claim with a negative amount); the date its rounding goes by (a correction's is the
 *  date of the claim it corrects, else its own). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  /** Who last edited it (its form or its amount entry); null when never edited. */
  editedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  /** Its due-by (YYYY-MM-DD): the business day its terms (fixed when it was created) count to after its date then, past the holidays now. */
  dueBy: string;
  /** Its status log, oldest first: one line per status it has had, `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** The date it is deferred until (YYYY-MM-DD), or null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: raised by one at a time (not on a SETTLED or VOID claim). */
  proofs: number;
  /** The number of the claim it was split off from, or null when it was not made by a split. */
  splitFrom: string | null;
  /** Whether it was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  remindedOn: string | null;
  /** Its external reference, trimmed (unique on the sheet, ignoring case), or null when it has none. */
  ref: string | null;
  /** Its tags, trimmed, lower-cased and sorted, without repeats; empty when it has none. */
  tags: string[];
  /** Every tag it has ever carried, sorted: the sheet's tags are those of all its claims. */
  tagsUsed: string[];
  /** The reason it was voided with, from the sheet's list, or null when it was voided without one (or is not VOID). */
  voidReason: string | null;
  /** Its comments, oldest first: `<user> on <date>: <text>`, dated the sheet's today when each was written. */
  comments: string[];
  /** The number of the bulk settle batch that settled it (or left it PENDING); null when settled one at a time. */
  settleBatch: number | null;
};

/** Whether a claim is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the live totals). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim shows and totals the figure its person's last statement bound it to: it is bound and not PENDING
 *  (a PENDING claim shows its live figure, and is bound again if rejected). */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: it is OPEN and deferred until a date after it. Until then it
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: Claim, today: string | undefined) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, but not a
 *  deferred one. */
export const counts = (c: Claim, today: string | undefined) => (isOpen(c) || c.status === 'SETTLED') && !isDeferred(c, today);

/** A hold: from a date on, to a date (YYYY-MM-DD, inclusive; null: open-ended). */
export type Hold = { from: string; to: string | null };

/** Each person's holds, and the date they are retired from (null: not retired), by person id. */

